import Foundation
import Testing
@testable import DarwinPackager

@Suite struct HostPackageTests {

    static let package = HostPackage(
        hostPackage: URL(fileURLWithPath: "/src/DarwinAppRuntime"),
        library: URL(fileURLWithPath: "/work/libapp-0123456789abcdef.a"),
        platform: .ios,
        deploymentTarget: "16.0",
        sdkVersion: "27.2"
    )

    @Test func writesTheManifest() {
        #expect(Self.package.manifest == """
            // swift-tools-version:6.0
            // Generated by darwin-app for ios; `darwin-app package` rewrites it.
            import PackageDescription

            let package = Package(
                name: "AppHost",
                platforms: [
                    .iOS("16.0"),
                    .macOS("12.0"),
                ],
                dependencies: [
                    .package(path: "/src/DarwinAppRuntime"),
                ],
                targets: [
                    .executableTarget(
                        name: "AppExecutable",
                        dependencies: [
                            .product(name: "DarwinHostApp", package: "DarwinAppRuntime"),
                        ],
                        linkerSettings: [
                            .unsafeFlags([
                                "/work/libapp-0123456789abcdef.a",
                                "-Xlinker",
                                "-platform_version",
                                "-Xlinker",
                                "ios",
                                "-Xlinker",
                                "16.0",
                                "-Xlinker",
                                "27.2",
                            ]),
                        ]
                    ),
                ]
            )

            """)
    }

    @Test func usesTheMacOSMinimumForMacOS() {
        var package = Self.package
        package.platform = .macos
        package.deploymentTarget = "13.0"
        #expect(package.manifest.contains(".iOS(\"15.0\"),\n        .macOS(\"13.0\"),"))
        #expect(package.manifest.contains("\"macos\","))
    }

    @Test func writesMainSwift() {
        #expect(HostPackage.mainSwift == """
            import DarwinHostApp

            HostApp.run(AppEntryPoints(main: rt_main, dispatch: rt_dispatch, finalize: rt_finalize))

            """)
    }

    @Test func findsThisRepository() {
        let root = HostPackage.defaultHostPackage
        #expect(FileManager.default.fileExists(atPath: root.appendingPathComponent("Package.swift").path))
        #expect(FileManager.default.fileExists(atPath: root.appendingPathComponent("Sources/DarwinHostApp").path))
    }

    @Test func writesThePackage() throws {
        let directory = try TemporaryDirectory()
        var package = Self.package
        package.hostPackage = HostPackage.defaultHostPackage
        try package.write(to: directory.url)
        #expect(try String(contentsOf: directory.file("Package.swift"), encoding: .utf8) == package.manifest)
        #expect(try String(contentsOf: directory.file("Sources/AppExecutable/main.swift"), encoding: .utf8) == HostPackage.mainSwift)
        #expect(FileManager.default.fileExists(atPath: directory.file(".swift-version").path))
        // Unchanged files keep their dates, so SwiftPM doesn't reload.
        let date = try FileManager.default.attributesOfItem(atPath: directory.file("Package.swift").path)[.modificationDate] as? Date
        try package.write(to: directory.url)
        #expect(try FileManager.default.attributesOfItem(atPath: directory.file("Package.swift").path)[.modificationDate] as? Date == date)
    }

    @Test func buildsForEachPlatform() {
        let directory = URL(fileURLWithPath: "/work/host")
        let swift = ["xcrun", "swift"]
        let ios = Self.package.buildCommand(directory: directory, configuration: .release, architectures: ["arm64"], sdkPath: "/SDKs/iPhoneOS.sdk", swift: swift, environment: ["APPRUNTIME_PATH": "/src/AppRuntime"])
        #expect(ios.description == "(cd /work/host && APPRUNTIME_PATH=/src/AppRuntime xcrun swift build -c release --package-path /work/host --product AppExecutable --triple arm64-apple-ios16.0 --sdk /SDKs/iPhoneOS.sdk)")
        #expect(ios.streamsOutput)

        var simulator = Self.package
        simulator.platform = .iosSimulator
        let simulatorBuild = simulator.buildCommand(directory: directory, configuration: .debug, architectures: ["arm64"], sdkPath: "/SDKs/iPhoneSimulator.sdk", swift: ["swift"], environment: [:])
        #expect(simulatorBuild.arguments == ["build", "-c", "debug", "--package-path", "/work/host", "--product", "AppExecutable", "--triple", "arm64-apple-ios16.0-simulator", "--sdk", "/SDKs/iPhoneSimulator.sdk"])

        var macos = Self.package
        macos.platform = .macos
        let macBuild = macos.binPathCommand(directory: directory, configuration: .release, architectures: ["arm64", "x86_64"], sdkPath: "/SDKs/MacOSX.sdk", swift: swift, environment: [:])
        #expect(macBuild.arguments == ["swift", "build", "-c", "release", "--package-path", "/work/host", "--product", "AppExecutable", "--arch", "arm64", "--arch", "x86_64", "--show-bin-path"])
        #expect(!macBuild.streamsOutput)
    }
}
